const encoded =
  '';
export function sourceImages() {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const values = [];
  let accumulator = 0,
    bits = 0;
  for (let i = 0; i < encoded.length; ++i) {
    const value = alphabet.indexOf(encoded[i]);
    if (value < 0) break;
    accumulator = (accumulator << 6) | value;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      values.push((accumulator >>> bits) & 255);
    }
  }
  return { 'nebbiaRaindrop.png': { width: 256, height: 256, pixels: new Uint8Array(values) } };
}
